import React, { useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const PaymentPending = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const orderId = localStorage.getItem("latestOrderId");

    if (!orderId) {
      navigate("/checkout");
      return;
    }

    const interval = setInterval(async () => {
      try {
        const res = await axios.get(`http://localhost:5000/order-status/${orderId}`);

        if (res.data.paymentStatus === "approved") {
          alert("Payment Successful ✅");
          clearInterval(interval);
          navigate("/order-success");
        }

        if (res.data.paymentStatus === "rejected") {
          alert("Payment not received ❌ Retry Payment");
          clearInterval(interval);
          navigate("/checkout");
        }
      } catch (err) {
        console.log("Status check error:", err);
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [navigate]);

  return (
    <div style={{ textAlign: "center", marginTop: "100px" }}>
      <h2>Payment Under Verification ⏳</h2>
      <p>We are checking your payment.</p>
      <p>Please wait for admin approval.</p>
    </div>
  );
};

export default PaymentPending;
